  "i18n": "i18n",
  "in-browser + live API": "wɛbu-kɔrɔsibaga kɔnɔ + API ɲɛnama",
  "inference_input — use as context at inference time (RAG)": "inference_input — kɛli i n'a fɔ sigida jatebɔ waati la (RAG)",
  "license required": "lisansi ka kan",
  "may proceed (with conditions)": "a bɛ se ka taama (saratiw kɔnɔ)",
  "missing": "dɛsɛlen",
  "not permitted": "sɔn tɛ a ma",
